export function MinistryDetail(i){return`\n        <div class="ministry-detail-content">\n            <div class="detail-section">\n                <h4>Responsibilities</h4>\n                <ul class="detail-list">${i.responsibilities.map(i=>`<li>${i}</li>`).join("")}</ul>\n            </div>\n            <div class="detail-section">\n                <h4>Departments</h4>\n                <ul class="detail-list">${i.departments.map(i=>`<li>${i}</li>`).join("")}</ul>\n            </div>\n            <div class="detail-section">\n                <h4>Organizational Structure</h4>\n                <p class="detail-text">${i.orgStructure}</p>\n            </div>\n            <div class="detail-meta">\n                <span class="meta-item"><strong>Established:</strong> ${i.established}</span>\n                <a class="meta-link" href="${i.website}" target="_blank" rel="noopener noreferrer">Official Website &rarr;</a>\n            </div>\n        </div>\n    `}